{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.freakins_inventory_ageing_consolidated as WITH daily_grn as ( SELECT DISTINCT c.date_day, g.item_skucode, g.category, FROM `MAPLEMONK.Freakins_GRN_Factitems` AS g CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(CURRENT_DATE(), YEAR), CURRENT_DATE())) AS date_day ) AS c ), GRN AS( select date(dg.date_day) as date, dg.item_skucode, dg.Category, sum(ifnull(Quantity_Received,0)) as Received_Quantity, sum(ifnull(Quantity_Rejected,0)) as Rejected_Quantity from daily_grn dg left join `MAPLEMONK.Freakins_GRN_Factitems` g on dg.date_day = cast(g.grn_date as date) and dg.item_skucode = g.item_skucode and dg.category = g.category group by 1,2,3 ), grn_month_wise AS ( select date_trunc(mg.date,month) as month, mg.item_skucode, mg.Category, CASE WHEN DATE_DIFF(DATE_TRUNC(CURRENT_DATE(),MONTH), date_trunc(mg.date,month), MONTH) = 0 THEN \'0-30\' WHEN DATE_DIFF(DATE_TRUNC(CURRENT_DATE(),MONTH), date_trunc(mg.date,month), MONTH) = 1 THEN \'30-60\' WHEN DATE_DIFF(DATE_TRUNC(CURRENT_DATE(),MONTH), date_trunc(mg.date,month), MONTH) = 2 THEN \'60-90\' WHEN DATE_DIFF(DATE_TRUNC(CURRENT_DATE(),MONTH), date_trunc(mg.date,month), MONTH) = 3 THEN \'90-120\' WHEN DATE_DIFF(DATE_TRUNC(CURRENT_DATE(),MONTH), date_trunc(mg.date,month), MONTH) = 4 THEN \'120-150\' WHEN DATE_DIFF(DATE_TRUNC(CURRENT_DATE(),MONTH), date_trunc(mg.date,month), MONTH) = 5 THEN \'150-180\' WHEN DATE_DIFF(DATE_TRUNC(CURRENT_DATE(),MONTH), date_trunc(mg.date,month), MONTH) = 6 THEN \'180-210\' WHEN DATE_DIFF(DATE_TRUNC(CURRENT_DATE(),MONTH), date_trunc(mg.date,month), MONTH) = 7 THEN \'210-240\' WHEN DATE_DIFF(DATE_TRUNC(CURRENT_DATE(),MONTH), date_trunc(mg.date,month), MONTH) = 8 THEN \'240-270\' END as Inventory_Ageing_Bucket, sum(ifnull(mg.Received_Quantity,0)) - sum(ifnull(mg.Rejected_Quantity,0)) as Monthly_Received_Quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 1 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w1_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 2 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w2_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 3 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w3_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 4 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w4_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 5 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w5_grn_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 6 then ifnull(mg.Received_Quantity,0) - ifnull(mg.Rejected_Quantity,0) end) as w6_grn_quantity from grn mg group by 1,2,3,4 ), grn_total as ( select item_skucode, category, sum(ifnull(Received_Quantity,0)) - sum(ifnull(Rejected_Quantity,0)) as Total_Inwarded_Quantity from grn group by 1,2 ), grn_cummulative as ( select g.month, g.item_skucode, g.category, sum(ifnull(g1.Monthly_Received_Quantity,0)) as Cummulative_Quantity from grn_month_wise g left join grn_month_wise g1 on g1.month < g.month and g1.item_skucode = g.item_skucode and g1.category = g.category group by 1,2,3 ), daily_sales as ( SELECT DISTINCT c.date_day, s.sku, s.Product_Category_Main as product_category, FROM `MAPLEMONK.Freakins_db_sales_consolidated` AS s CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(CURRENT_DATE(), YEAR), CURRENT_DATE())) AS date_day ) AS c ), sales AS ( select date(ds.date_day) as date, ds.sku as sku, ds.Product_Category, sum(ifnull(Quantity,0)) as Sold_Quantity from daily_sales ds left join `MAPLEMONK.Freakins_db_sales_consolidated` s on ds.date_day = cast(s.order_date as date) and lower(ds.sku) = lower(s.sku) and lower(ds.product_category) = lower(s.Product_Category_Main) group by 1,2,3 ), sales_month_wise as ( select date_trunc(date,month) month, sku, product_category, sum(ifnull(s.sold_quantity,0)) as monthly_sold_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 1 then ifnull(s.sold_quantity,0) end) as w1_sold_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 2 then ifnull(s.sold_quantity,0) end) as w2_sold_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 3 then ifnull(s.sold_quantity,0) end) as w3_sold_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 4 then ifnull(s.sold_quantity,0) end) as w4_sold_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 5 then ifnull(s.sold_quantity,0) end) as w5_sold_quantity, sum(case when (CEIL((EXTRACT(DAY FROM date) + EXTRACT(DAYOFWEEK FROM DATE_TRUNC(date, MONTH)) - 1) / 7)) = 6 then ifnull(s.sold_quantity,0) end) as w6_sold_quantity from sales s group by 1,2,3 ), sales_final as ( select s.*, ifnull(s30_60.monthly_sold_quantity,0) + ifnull(s.monthly_sold_quantity,0) as Sold_Quantity_60, ifnull(s60_90.monthly_sold_quantity,0) + ifnull(s30_60.monthly_sold_quantity,0) + ifnull(s.monthly_sold_quantity,0) as Sold_Quantity_90 from sales_month_wise s left join sales_month_wise s30_60 on s30_60.month = date_sub(s.month,interval 1 month) and s30_60.sku = s.sku and s30_60.product_category = s.product_category left join sales_month_wise s60_90 on s60_90.month = date_sub(s.month,interval 2 month) and s60_90.sku = s.sku and s60_90.product_category = s.product_category ), current_stock as ( SELECT Data_Fetch_Date, Sku, category, Available_Inventory FROM ( SELECT Data_Fetch_Date, Sku, category, Available_Inventory, ROW_NUMBER() OVER (PARTITION BY Sku,category ORDER BY Data_Fetch_Date DESC) AS rw FROM maplemonk.freakins_inventory_fact_items ) WHERE rw = 1 ) select g.*, sm.style_code, sm.Product_ID, sm.Product_title, s.w1_sold_quantity, s.w2_sold_quantity, s.w3_sold_quantity, s.w4_sold_quantity, s.w5_sold_quantity, s.w6_sold_quantity, s.monthly_sold_quantity as Sold_Quantity_30, s.Sold_Quantity_60, s.Sold_Quantity_90, cs.available_inventory as Current_Stock, SUM(cs.available_inventory) OVER (PARTITION BY g.category) AS category_current_stock, SUM(cs.available_inventory) OVER (PARTITION BY sm.style_code) AS style_current_stock, CASE WHEN (gt.Total_Inwarded_Quantity - cs.available_inventory) < (gc.Cummulative_Quantity + g.Monthly_Received_Quantity) THEN CASE WHEN gc.Cummulative_Quantity > (gt.Total_Inwarded_Quantity - cs.available_inventory) THEN g.Monthly_Received_Quantity ELSE g.Monthly_Received_Quantity - ((gt.Total_Inwarded_Quantity - cs.available_inventory) - gc.Cummulative_Quantity) END ELSE 0 END as Current_Ageing_Inventory from grn_month_wise g left join sales_final s on s.month = g.month and s.sku = g.item_skucode and s.product_category = g.category left join `MAPLEMONK.FREAKINS_FINALL_SKU_MASTER` sm on lower(replace(sm.variant_sku,\' \',\'\')) = lower(g.item_skucode) left join current_stock cs on lower(cs.sku) = lower(g.item_skucode) and lower(cs.category) = lower(g.category) left join grn_total gt on lower(gt.item_skucode) = lower(g.item_skucode) and lower(gt.category) = lower(g.category) left join grn_cummulative gc on lower(gc.item_skucode) = lower(g.item_skucode) and gc.month = g.month and lower(gc.category) = lower(g.category) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            